create or replace function public.prepare_universal_location_discovery(p_lat double precision, p_lng double precision, p_radius_m integer default 16093, p_user_id uuid default auth.uid()) returns jsonb language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $function$ declare v_radius integer:=greatest(1000,least(coalesce(p_radius_m,16093),50000)); v_tier text; v_session uuid; v_locations jsonb; v_lat_delta double precision; v_lng_delta double precision; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_user_id is distinct from auth.uid() then raise exception 'User identity mismatch'; end if; if p_lat is null or p_lng is null or p_lat < -90 or p_lat > 90 or p_lng < -180 or p_lng > 180 then raise exception 'valid coordinates required'; end if; select subscription_tier::text into v_tier from profiles where id=auth.uid(); insert into user_location_sessions(user_id,latitude,longitude,radius_meters,tier_code) values(auth.uid(),p_lat,p_lng,v_radius,v_tier) returning id into v_session; v_lat_delta:=v_radius/111320.0; v_lng_delta:=v_radius/(111320.0*greatest(cos(radians(p_lat)),0.1)); select coalesce(jsonb_agg(to_jsonb(x) order by x.distance_meters),'[]'::jsonb) into v_locations from (select l.id,l.name,l.address,l.city,l.state,l.postal_code,l.latitude,l.longitude,l.place_type,l.source,l.source_dataset,l.source_external_id,l.source_metadata,l.verification_status,l.bathroom_verification_status,l.accessible,l.changing_table,l.cleanliness,l.cleanliness_pct,l.rating,l.review_count,l.updated_at,round((6371000*2*asin(sqrt(power(sin(radians(l.latitude-p_lat)/2),2)+cos(radians(p_lat))*cos(radians(l.latitude))*power(sin(radians(l.longitude-p_lng)/2),2))))::numeric,1) distance_meters from locations l where l.is_active=true and l.latitude between p_lat-v_lat_delta and p_lat+v_lat_delta and l.longitude between p_lng-v_lng_delta and p_lng+v_lng_delta order by distance_meters limit 1000) x where x.distance_meters<=v_radius; update user_location_sessions set last_seen_at=now(),metadata=jsonb_build_object('location_count',jsonb_array_length(v_locations)) where id=v_session; return jsonb_build_object('session_id',v_session,'tier',coalesce(v_tier,'free'),'radius_meters',v_radius,'locations',v_locations,'needs_external_discovery',jsonb_array_length(v_locations)=0,'data_policy','universal_discovery_v1'); end $function$;
create or replace function public.record_favorite_route_event(p_location_id uuid, p_user_id uuid default null, p_from_lat numeric default null, p_from_lng numeric default null) returns uuid language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $function$ declare v_id uuid; v_user uuid:=auth.uid(); begin if v_user is null then raise exception 'Authentication required'; end if; if p_user_id is not null and p_user_id is distinct from v_user then raise exception 'User identity mismatch'; end if; insert into public.location_route_events(location_id,user_id,source,from_lat,from_lng) values(p_location_id,v_user,'favorite',p_from_lat,p_from_lng) returning id into v_id; return v_id; end; $function$;
create or replace function public.refresh_contributor_milestones(p_user_id uuid) returns table(milestone_key text,achieved boolean,progress integer,target integer,points_awarded integer) language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $function$ declare obs integer; checks integer; reviews integer; m text; target_value integer; reward integer; already boolean; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_user_id is distinct from auth.uid() then raise exception 'User identity mismatch'; end if; select coalesce(observations_count,0),coalesce(verified_checkins_count,0) into obs,checks from contributor_reputation where user_id=auth.uid(); select coalesce(total_reviews,0) into reviews from profiles where id=auth.uid(); for m,target_value,reward in values ('first_observation',1,10),('five_observations',5,25),('first_verified_checkin',1,15),('five_verified_checkins',5,50),('trusted_contributor',8,75),('verified_contributor',20,150) loop if m='first_observation' then progress:=least(obs,target_value); elsif m='five_observations' then progress:=least(obs,target_value); elsif m='first_verified_checkin' then progress:=least(checks,target_value); elsif m='five_verified_checkins' then progress:=least(checks,target_value); elsif m='trusted_contributor' then progress:=least(obs,target_value); else progress:=least(obs,target_value); end if; if m='trusted_contributor' then achieved:=obs>=8 and checks>=4; elsif m='verified_contributor' then achieved:=obs>=20 and checks>=10; else achieved:=progress>=target_value; end if; already:=exists(select 1 from contributor_milestones where user_id=auth.uid() and milestone_key=m); if achieved and not already then insert into contributor_milestones(user_id,milestone_key,points_awarded) values(auth.uid(),m,reward); insert into reward_transactions(user_id,points,reason,metadata) values(auth.uid(),reward,'contributor_milestone',jsonb_build_object('milestone',m)); update profiles set points=coalesce(points,0)+reward where id=auth.uid(); points_awarded:=reward; else points_awarded:=case when already then 0 else reward end; end if; milestone_key:=m; target:=target_value; return next; end loop; end; $function$;
create or replace function public.refresh_contributor_reputation(p_user_id uuid) returns contributor_reputation language plpgsql security definer set search_path to 'public','auth','extensions','pg_temp' as $function$ declare r public.contributor_reputation; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_user_id is distinct from auth.uid() then raise exception 'User identity mismatch'; end if; insert into public.contributor_reputation(user_id) values(auth.uid()) on conflict(user_id) do nothing; update public.contributor_reputation cr set observations_count=(select count(*) from public.restroom_observations ro where ro.user_id=auth.uid()),verified_checkins_count=(select count(*) from public.check_ins ci where ci.user_id=auth.uid() and coalesce(ci.verified,true)=true),positive_observations_count=(select count(*) from public.restroom_observations ro where ro.user_id=auth.uid() and ro.observation_type in ('clean','supplies_stocked','open')),negative_observations_count=(select count(*) from public.restroom_observations ro where ro.user_id=auth.uid() and ro.observation_type in ('needs_cleaning','supplies_low','closed_unavailable')),last_activity_at=greatest((select max(ro.created_at) from public.restroom_observations ro where ro.user_id=auth.uid()),(select max(ci.created_at) from public.check_ins ci where ci.user_id=auth.uid())),updated_at=now() where cr.user_id=auth.uid(); update public.contributor_reputation cr set confirmed_observations_count=least(cr.observations_count,cr.verified_checkins_count),reputation_score=least(100,cr.observations_count*5+cr.verified_checkins_count*8+cr.confirmed_observations_count*4+greatest(0,cr.positive_observations_count-cr.negative_observations_count)*2),verification_level=case when cr.observations_count>=20 and cr.verified_checkins_count>=10 then 'verified' when cr.observations_count>=8 and cr.verified_checkins_count>=4 then 'trusted' when cr.observations_count>=2 then 'contributor' else 'new' end where cr.user_id=auth.uid(); select * into r from public.contributor_reputation where user_id=auth.uid(); return r; end; $function$;
